-- Align the Sandy Sports drafts with draft constitution Rule 4B.
-- Sandy source revision: 1c4983243c8fad3779ca1b2a96c8f59271452177.
-- Only update the original unauthored drafts at their expected edit versions.

UPDATE learning_course_versions SET
  description='Rehearse PLFC''s consent-based capture and Sandy''s draft Rule 4B. Work through a full meeting recording, checked minutes, a member archive and a public replay.',
  lessons_json=json_set(lessons_json,
    '$[0]', json('{"title":"Use the club’s rule and assign the jobs","body":"Identify the club, meeting type and governing authority before preparing the capture. PLFC uses its own meeting decision and participant consent. Sandy is in formation. Its draft constitution Rule 4B calls for full video and audio for committee and general meetings, including the AGM, from opening to close without pausing. The Secretary is responsible for recording and archiving. The Secretary or Assistant Secretary makes the recording, and Film Club crew may operate the equipment. Officers with Members and publishing access under Schedule 1 approve public streams. Check who will minute, record, operate, approve and verify the feed before the meeting.","captureNotes":"Compare the PLFC recording panel and Sandy’s Rule 4B flow. Show a fictional roster with the Secretary, deputy, crew operator and public publishing officer. Reference: https://github.com/auraofintelligence/Sandy-Sports-Club/blob/1c4983243c8fad3779ca1b2a96c8f59271452177/constitution.js","questions":[{"id":"practice-1","type":"single_choice","mode":"practice","prompt":"The Film Club producer has an encoder and a draft public listing. Who approves a Sandy public meeting stream?","choices":[{"id":"a","text":"Anyone rostered on the Film Club crew."},{"id":"b","text":"An officer with Members and publishing access under Schedule 1."},{"id":"c","text":"The person with the fastest uplink."}],"correct_choice_id":"b","explanation":"The Secretary coordinates recording and archiving, and the designated Schedule 1 group approves the public stream.","source_refs":["https://github.com/auraofintelligence/Sandy-Sports-Club/blob/1c4983243c8fad3779ca1b2a96c8f59271452177/constitution.js"]},{"id":"practice-2","type":"single_choice","mode":"practice","prompt":"Which Sandy meetings does Rule 4B(a) explicitly include?","choices":[{"id":"a","text":"Only AGMs and meetings that pass a separate recording motion."},{"id":"b","text":"Every informal working-group chat."},{"id":"c","text":"Every committee and general meeting, including the AGM."}],"correct_choice_id":"c","explanation":"Rule 4B(a) covers formal committee and general meetings. A public forum also has the public stream rule in Rule 4B(d).","source_refs":["https://github.com/auraofintelligence/Sandy-Sports-Club/blob/1c4983243c8fad3779ca1b2a96c8f59271452177/constitution.js"]}]}'),
    '$[1]', json('{"title":"Give notice and choose the audience","body":"At PLFC, explain the proposed capture, any browser speech provider, intended audience and handling. Check agreement before capture and use written minutes if recording is not authorised. If a public session moves to closed business under its own rules, verify the public feed and public capture have ended before discussing the closed item.\n\nAt Sandy, nomination includes an agreement to recording, archiving and member access under Rule 4B. General and public meeting notices state that the meeting is recorded, and public notices also state that the meeting is broadcast publicly. Committee recordings go to the member archive. General meetings may also be streamed live to members. Public meetings go live publicly and keep a public replay. Resolve a sensitive agenda or uncertainty about authority with the Secretary before opening. Rule 4B does not plan a pause in the meeting recording.","captureNotes":"Draft a Sandy general meeting notice and a public meeting notice. Show the expected member or public audience and the recording disclosure. Reference: https://github.com/auraofintelligence/Sandy-Sports-Club/blob/1c4983243c8fad3779ca1b2a96c8f59271452177/constitution.js","questions":[{"id":"practice-1","type":"single_choice","mode":"practice","prompt":"You are issuing a Sandy public forum notice. Which disclosure belongs on it?","choices":[{"id":"a","text":"State that the meeting is recorded and streamed live to the public."},{"id":"b","text":"Say it may be filmed without describing the public feed."},{"id":"c","text":"Announce capture only after the public feed starts."}],"correct_choice_id":"a","explanation":"The draft rule makes the intended capture and public stream part of the advance notice.","source_refs":["https://github.com/auraofintelligence/Sandy-Sports-Club/blob/1c4983243c8fad3779ca1b2a96c8f59271452177/constitution.js"]},{"id":"practice-2","type":"single_choice","mode":"practice","prompt":"A Sandy organiser wants a general meeting feed for members only. What do you set up?","choices":[{"id":"a","text":"Use the public Island News live bar and ask members not to share it."},{"id":"b","text":"Use a member-authorised host and test it from member and signed-out views."},{"id":"c","text":"Give guests the private stream key so they can try both routes."}],"correct_choice_id":"b","explanation":"Member-only coverage requires access at the host as well as using the agreed member delivery route.","source_refs":["https://github.com/auraofintelligence/Sandy-Sports-Club/blob/1c4983243c8fad3779ca1b2a96c8f59271452177/constitution.js"]}]}'),
    '$[2]', json('{"title":"Capture the full meeting and verify the file","body":"At PLFC, use the meeting controls for approved mic audio or camera and audio. Select the input, record a short test and download after stopping. Its browser speech recognition may start with capture if supported, with possible network processing. Explain that before using the combined consent control.\n\nFor Sandy Rule 4B, arrange an external camera or encoder to capture continuous video and intelligible audio from opening to close. Test the planned full-length recording setup, recording space, power, audio and backup before the Chair opens. Check the recorded file for both picture and sound. Sandy’s local audio tool can cover an audio task. The Rule 4B meeting archive stores links to the hosted artefacts. If equipment or internet fails, keep the independent backup running, report the gap and preserve what was captured.","captureNotes":"Show the PLFC local-download control and a fictional Sandy camera/encoder capturing simultaneous video and audio. Rehearse an uplink loss with the recording still running. Reference: https://github.com/auraofintelligence/Sandy-Sports-Club/blob/1c4983243c8fad3779ca1b2a96c8f59271452177/club-meetings.js","questions":[{"id":"practice-1","type":"single_choice","mode":"practice","prompt":"Sandy’s internet connection drops halfway through a public meeting. The local encoder is still recording. What do you do?","choices":[{"id":"a","text":"Pause the local recording until the public player is back."},{"id":"b","text":"Discard the first half and start a new master when online."},{"id":"c","text":"Keep the local master running, alert the Secretary and publishing officer, log the outage and restore the feed where possible."}],"correct_choice_id":"c","explanation":"Independent local capture preserves the meeting when the external stream fails.","source_refs":["https://github.com/auraofintelligence/Sandy-Sports-Club/blob/1c4983243c8fad3779ca1b2a96c8f59271452177/club-meetings.js"]},{"id":"practice-2","type":"single_choice","mode":"practice","prompt":"The only Sandy file after rehearsal is a local audio download. What does that tell you?","choices":[{"id":"a","text":"Audio worked. Arrange and verify continuous video capture before a covered meeting opens."},{"id":"b","text":"The audio file is the complete Rule 4B record."},{"id":"c","text":"Upload the file and use the same link in the video field."}],"correct_choice_id":"a","explanation":"Rule 4B requires video and audio. The audio-only tool provides only one part.","source_refs":["https://github.com/auraofintelligence/Sandy-Sports-Club/blob/1c4983243c8fad3779ca1b2a96c8f59271452177/club-meetings.js"]}]}'),
    '$[3]', json('{"title":"Transcribe under club control and check minutes","body":"For Sandy, use a transcript workflow controlled by the club. Agree who can process the source, then verify the transcript against the recording. Check names, money amounts, exact motions, votes and dates, and flag unclear sections with timestamps before filing. Retain archived source recordings and transcripts intact. Minutes remain the formal record of decisions. If minutes and recording differ, refer the timestamp and proposed wording to the committee and record the committee’s approved minutes correction. The minutes record, transcript and recording each retain their purpose.\n\nAt PLFC, the authorised browser transcript can be edited or manually supplied. Verify any optional AI draft from approved text and take the reviewed minutes through PLFC’s own approval process.","captureNotes":"Use fictional audio with a misheard vote and show a timestamped correction proposal for Sandy. Show PLFC’s own draft transcript option separately. Reference: https://github.com/auraofintelligence/Sandy-Sports-Club/blob/1c4983243c8fad3779ca1b2a96c8f59271452177/constitution.js","questions":[{"id":"practice-1","type":"single_choice","mode":"practice","prompt":"The Sandy recording and approved minutes disagree about the outcome of a motion. What happens next?","choices":[{"id":"a","text":"Edit the recording so it agrees with the minutes."},{"id":"b","text":"Refer the timestamp and wording to the committee for a minutes correction and preserve the archived media."},{"id":"c","text":"Replace the formal minutes with the saved transcript."}],"correct_choice_id":"b","explanation":"The minutes remain the formal record. The recording is evidence the committee can use when correcting them.","source_refs":["https://github.com/auraofintelligence/Sandy-Sports-Club/blob/1c4983243c8fad3779ca1b2a96c8f59271452177/constitution.js"]},{"id":"practice-2","type":"single_choice","mode":"practice","prompt":"Someone suggests uploading a Sandy meeting to their personal transcription account. What do you arrange instead?","choices":[{"id":"a","text":"Use a personal account and delete the local source afterwards."},{"id":"b","text":"Use the public replay link for both the transcript and minutes."},{"id":"c","text":"Use an agreed tool the club controls, check the transcript before filing and preserve the archive."}],"correct_choice_id":"c","explanation":"Rule 4B specifies club-controlled tools and keeping the transcript alongside the recording.","source_refs":["https://github.com/auraofintelligence/Sandy-Sports-Club/blob/1c4983243c8fad3779ca1b2a96c8f59271452177/constitution.js"]}]}'),
    '$[4]', json('{"title":"Run a public stream and retain the replay","body":"For a Sandy public meeting or forum, the authorised publishing officer approves the public stream. The crew starts the encoder and host and a separate viewer checks the actual feed. In Island news and live, schedule the public viewer link and set the listing to Live when the host is confirmed. Keep full local video and audio running through opening to close. End the provider feed after the meeting, confirm it externally and update the Sandy listing. Add the complete public replay and verify that it plays. A permitted network handoff goes through its steward. If a general meeting is streamed to members, use the member-authorised route and verify the host denies signed-out viewers.","captureNotes":"Show a synthetic OBS source, Island News listing and outside viewer. Demonstrate a member-only link check and the public replay path with separate test assets. Reference: https://sandy-sports-club.auraofintelligence.workers.dev/how-it-works.html#flow-broadcast","questions":[{"id":"practice-1","type":"single_choice","mode":"practice","prompt":"The Sandy listing says Live but the external viewer is still waiting for video. Where do you check first?","choices":[{"id":"a","text":"Check the encoder and host, and make the public listing reflect what viewers can reach."},{"id":"b","text":"Refresh Sandy until the site starts encoding video."},{"id":"c","text":"Publish the stream key so viewers can start the host."}],"correct_choice_id":"a","explanation":"Sandy lists the broadcast. The host and encoder carry it.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/how-it-works.html#flow-broadcast"]},{"id":"practice-2","type":"single_choice","mode":"practice","prompt":"Where does the complete replay of a Sandy public meeting go after the broadcast?","choices":[{"id":"a","text":"Only in a private folder accessible to the Film Club crew."},{"id":"b","text":"On Island news and live, with the meeting’s archive records filed through the Secretary."},{"id":"c","text":"Only in a highlights package with parts of the meeting cut out."}],"correct_choice_id":"b","explanation":"Rule 4B keeps the public recording as a replay and keeps the meeting record in the archive.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/how-it-works.html#flow-broadcast"]}]}'),
    '$[5]', json('{"title":"File Sandy’s permanent archive and verify access","body":"For Sandy, preserve the original video, audio and transcript on club-controlled hosting with the correct audience. Open the meeting’s minutes step and save stable HTTPS links in Meeting archive (rule 4B). Keep the minutes in the corresponding official meeting record. Check Watch, Listen and Transcript under My Membership, Notices & newsletters, Meeting archive. Test the actual media links with a member and a signed-out view. The site controls who sees its index. The hosting service must enforce the same audience for member-only files. Rule 4B keeps the recordings and transcripts permanently without edits. If a link moves, replace it through the archive so history records the old link, and check a restored backup. For PLFC, follow its own approved records schedule and access arrangements.","captureNotes":"Use a fictional meeting’s step 3 archive form and the member Notices tab. Test both hosting audiences and show how replacing a broken URL retains link history. Reference: https://sandy-sports-club.auraofintelligence.workers.dev/how-it-works.html#flow-recording","questions":[{"id":"practice-1","type":"single_choice","mode":"practice","prompt":"A Sandy member archive video is indexed behind sign-in, but the video URL plays for anyone. What is the next action?","choices":[{"id":"a","text":"Assume the Sandy sign-in protects the video once someone copies its URL."},{"id":"b","text":"Move the same link into the public Island News listing."},{"id":"c","text":"Set appropriate access at the host and repeat member and signed-out checks."}],"correct_choice_id":"c","explanation":"Portal visibility and the media host’s own link permissions are separate controls.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/how-it-works.html#flow-recording"]},{"id":"practice-2","type":"single_choice","mode":"practice","prompt":"The server migration changes the archived recording''s URL. What is the correct handoff?","choices":[{"id":"a","text":"Preserve the original recording and replace its link through the archive, retaining the link history."},{"id":"b","text":"Clear the archive field and delete the old master."},{"id":"c","text":"Trim the recording before moving it to the new store to save space."}],"correct_choice_id":"a","explanation":"The archive permits a replacement link and keeps the old reference. The record itself is permanent.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/how-it-works.html#flow-recording"]}]}')
  ),
  practical='Use fictional material. Rehearse two meetings. For PLFC, show the approval and consent plan, local download, checked transcript and restricted handoff. For Sandy, produce a notice, nomination consent check, recorded opening-to-close video and audio with a backup, a club-controlled transcript, draft minutes and a permanent archive entry. Demonstrate member versus public access, show who approves a public stream and hand over a complete public replay. Simulate loss of the public connection without stopping the local master and use a timestamp to propose a minutes correction. The assessor checks the audience, authority, continuity, access and integrity of each record.',
  edit_version=edit_version+1
WHERE course_id='meeting-media-operator' AND revision=1 AND state='draft' AND edit_version=1 AND edited_by IS NULL;

UPDATE learning_course_versions SET
  lessons_json=json_set(lessons_json,
    '$[1]', json('{"title":"Prepare meeting papers and support the record","body":"Check papers, draft agenda, circulated versions, relevant notices and nominations with the Secretary. Flag a missing report or changed motion while it is still useful to reschedule or correct. In approved cover, record the actual outcome, attendance and actions and route sensitive working notes appropriately. Review any transcript suggestions against what was agreed before the next version is shared.\n\nKeep the agenda and notice versions, source papers, decision and update owner in the authorised record.\n\nWhen delegated under Sandy’s draft Rule 4B, prepare the opening-to-close video and audio, check the recorder and backup, and tell the Secretary about any capture gap. Keep the original files intact. Use the club-controlled transcript workflow, check the text against timestamps and give the Secretary the files and verified links for the permanent archive. In the minutes step, use the Rule 4B archive under the Secretary’s direction. For a rehearsal, see Meeting recording, transcription and archives in Ready SETCO Skills & Work.","captureNotes":"Show continuous video and audio, the Secretary’s delegated recording and an archive handoff in a fictional meeting. Reference: https://sandy-sports-club.auraofintelligence.workers.dev/how-it-works.html#flow-recording","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"You find an amended agenda after members received the notice. What do you do first?","choices":[{"id":"a","text":"Confirm what was sent and which authorised correction or next process applies."},{"id":"b","text":"Put the amended version on the public calendar so everyone sees the latest file."}],"correct_choice_id":"a","explanation":"The operating record needs the agenda and notice versions, source papers, decision and update owner. This lets the next person verify the work and any remaining decision.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]},{"id":"practice-2","type":"single_choice","mode":"practice","prompt":"The only file your recorder produced is an audio download. What do you tell the Secretary?","choices":[{"id":"a","text":"Mark the archive complete because the minutes are detailed."},{"id":"b","text":"Explain the video gap, preserve the audio and backup, and record a full video-and-audio test before the next covered meeting."},{"id":"c","text":"Put the audio link in both video and audio fields."}],"correct_choice_id":"b","explanation":"The deputy reports gaps accurately and hands over the captured evidence. Full video and audio must be prepared.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/how-it-works.html#flow-recording"]}]}')
  ),
  practical='Create a fictional shared secretarial handover covering a meeting paper change, actions from minutes, a linked notice and returned job sheet, AGM or formation dependencies, newsletter review, a queued message and a membership or safety referral. Show the approved scope, restricted record references, owner and next date for each. Pass when the Secretary can reproduce the current version, confirm what may be done under cover and identify what still needs a decision. Include a timed rehearsal with continuous video and audio, a club-controlled transcript and an archive-link repair. Show what the Secretary remains responsible for.',
  edit_version=edit_version+1
WHERE course_id='sandy-assistant-secretary' AND revision=1 AND state='draft' AND edit_version=3 AND edited_by IS NULL;

UPDATE learning_course_versions SET
  lessons_json=json_set(lessons_json,
    '$[1]', json('{"title":"Prepare meetings and handle conflicts","body":"Agree the purpose, notice, papers, eligible participants and current status of each item with the Secretary. Chair a fictional meeting using the relevant adopted or proposed rules explicitly for its status. Record interests, how participation changes, quorum and the outcome of each item. If the authority or rule is unclear, record the reason to defer. Ask the Secretary to read back the agreed wording, owners and deadlines. Separate decisions on planning from future formal votes.\n\nKeep the meeting basis, disclosures, wording and action owner, with draft or formal status in the authorised record.\n\nCheck Sandy’s draft Rule 4B with the Secretary before you open a committee or general meeting. Confirm continuous video and audio and ask for the opening recording cue. For a public meeting, confirm the notice and public stream permission with the Schedule 1 publishing officer and Film Club crew. Resolve material that cannot be handled within the planned recorded meeting before opening. Report any incident or recording gap instead of treating a pause as part of the protocol. If the archive shows the minutes are inaccurate, put the correction to the committee.","captureNotes":"Show a fictional opening cue, audience check and reference to a proposed minutes correction. Reference: https://github.com/auraofintelligence/Sandy-Sports-Club/blob/1c4983243c8fad3779ca1b2a96c8f59271452177/constitution.js","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A group discusses a proposed rule and appears to agree informally. How do you record it?","choices":[{"id":"a","text":"Record the discussion and any agreed planning action, and identify the proper process for adopting rules."},{"id":"b","text":"Mark the rule adopted because none of the people present objected."}],"correct_choice_id":"a","explanation":"The operating record needs the meeting basis, disclosures, wording and action owner, with draft or formal status. This lets the next person verify the work and any remaining decision.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]},{"id":"practice-2","type":"single_choice","mode":"practice","prompt":"A fictional public forum is ready to open but the archive recorder has not passed its video check. What should the Chair do?","choices":[{"id":"a","text":"Open anyway and record video after the first agenda item."},{"id":"b","text":"Hold the opening while the Secretary and crew resolve the recording check and confirm the stream with the authorised officer."},{"id":"c","text":"Start with an unrecorded discussion and publish only the highlights."}],"correct_choice_id":"b","explanation":"The Chair verifies readiness before the opening so the formal recording can run continuously.","source_refs":["https://github.com/auraofintelligence/Sandy-Sports-Club/blob/1c4983243c8fad3779ca1b2a96c8f59271452177/constitution.js"]}]}')
  ),
  practical='Chair a fictional founding discussion, then prepare the decision and handover pack for a proposed sports and film trial. Include proposed versus agreed authority, rules and notice check, a disclosure and quorum case, the actual wording and follow-up of a decision, venue and funding dependencies, safeguarding and an approved communications route. Identify when a formal decision would become available. Pass when each unresolved dependency stays visible and no draft authority is treated as a commitment. Show a Rule 4B chairing decision before opening, including notice, uninterrupted video and audio, and the handoff to the publishing officer if the meeting is public.',
  edit_version=edit_version+1
WHERE course_id='sandy-president' AND revision=1 AND state='draft' AND edit_version=3 AND edited_by IS NULL;

UPDATE learning_course_versions SET
  lessons_json=json_set(lessons_json,
    '$[0]', json('{"title":"Agree deputy cover and access","body":"Check the prospective role status and what authority has actually been recorded. Agree when you would cover the Chair and which decisions you can facilitate, recommend or refer. Read the actual meeting basis, agenda and possible conflicts before acting. Use your own approved access and check which member or safeguarded records your role can open.\n\nKeep the cover and role status, permitted actions and decision owners in the authorised record.\n\nWhen covering as Chair, confirm the Secretary or Assistant Secretary is running the Rule 4B recording and knows the opening and closing cues. Require continuous video and audio for a committee or general meeting. If a public stream is planned, check the wording of the notice, the publishing officer’s approval and the external viewer confirmation before opening. If connection fails, protect the local capture and arrange an accurate status update with the publishing officer.","captureNotes":"Show the deputy taking over a fictional meeting, with the recording and public approval handoff distinguished. Reference: https://sandy-sports-club.auraofintelligence.workers.dev/how-it-works.html#flow-recording","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"The Chair asks you to run a discussion but a commitment is proposed during it. What do you check?","choices":[{"id":"a","text":"Check the scope of your cover and take the commitment through the current authorised decision process."},{"id":"b","text":"Assume the cover includes authority for every item discussed."}],"correct_choice_id":"a","explanation":"The operating record needs the cover and role status, permitted actions and decision owners. This lets the next person verify the work and any remaining decision.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]},{"id":"practice-2","type":"single_choice","mode":"practice","prompt":"As acting Chair, who takes responsibility for the video, audio and transcripts in the Rule 4B archive?","choices":[{"id":"a","text":"The Vice President automatically replaces the Secretary as archive custodian."},{"id":"b","text":"The Film Club operator takes control of the official archive by running the equipment."},{"id":"c","text":"The Secretary, with the delegated Assistant Secretary able to carry out the recording or archive work."}],"correct_choice_id":"c","explanation":"Acting chair cover changes who runs the meeting. The Secretary remains responsible for recording and archiving.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/how-it-works.html#flow-recording"]}]}')
  ),
  practical='Give a fictional cover and coordination pack for a meeting, two competing venue requests and a proposed community event. Show the scope of delegation, how you would resolve an unowned task, approval and safeguarding gaps, a pause decision, a partner or gear dependency and the cleared next update. Pass when the chair and successor can see what the deputy may do, whose decision is needed and which real commitments are still open. For the chair cover, record the Rule 4B equipment and audience checks and show who takes responsibility for the archive.',
  edit_version=edit_version+1
WHERE course_id='sandy-vice-president' AND revision=1 AND state='draft' AND edit_version=3 AND edited_by IS NULL;

UPDATE learning_course_versions SET
  lessons_json=json_set(lessons_json,
    '$[1]', json('{"title":"Call a meeting and prepare the notice and papers","body":"Confirm purpose and meeting status, accountable convenor, agenda, date, venue or remote access, papers and audience. Check notice and voting arrangements against the appropriate source for the meeting status. Document what was sent and when. Flag late items, uncertain nominations and missing reports so the Chair can decide how to handle them. Keep proposed and confirmed dates separate in public information.\n\nKeep the notice, source and delivery record, venue status and linked agenda version in the authorised record.\n\nFor Sandy’s draft Rule 4B, every general and public meeting notice tells invitees the meeting is recorded. The public notice also says it is streamed live to the public. Use the standard agenda’s recording item, name the recording operator, test continuous audio and video before opening and confirm the audience and any public approval with the Schedule 1 publishing officer.","captureNotes":"Show the Rule 4B agenda item and compare fictional public and general meeting notices. Reference: https://sandy-sports-club.auraofintelligence.workers.dev/how-it-works.html#flow-recording","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A notice draft names a venue that is still being discussed. What changes before circulation?","choices":[{"id":"a","text":"Confirm the meeting’s arrangements and record any unresolved location before issuing a proper notice."},{"id":"b","text":"Assume the venue name is safe because it appears in the planning desk."}],"correct_choice_id":"a","explanation":"The operating record needs the notice, source and delivery record, venue status and linked agenda version. This lets the next person verify the work and any remaining decision.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]},{"id":"practice-2","type":"single_choice","mode":"practice","prompt":"What do you add to a public general meeting notice under Sandy’s draft Rule 4B?","choices":[{"id":"a","text":"State only that the minutes will be available."},{"id":"b","text":"State that the meeting is recorded and streamed live to the public."},{"id":"c","text":"Wait until after opening to disclose that the meeting is recorded."}],"correct_choice_id":"b","explanation":"The notice discloses recording in advance and identifies the public stream for a public meeting.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/how-it-works.html#flow-recording"]}]}'),
    '$[2]', json('{"title":"Minute decisions and preserve the approval trail","body":"Keep attendance, quorum where applicable, interest declarations, actual wording, outcomes and follow-up owners in the appropriate record. Label transcript or AI-assisted text as draft and check it against the actual discussion. Clear any use of recordings or processing with the responsible people. Reconcile the final minutes with officer tasks. Use version and history to preserve what was amended, reviewed and released to the right audience.\n\nKeep the corrected draft, actual decision, approval version and resulting actions in the authorised record.\n\nYou are responsible for Sandy’s draft Rule 4B recording and archive. Make the uninterrupted video and audio yourself or delegate to the Assistant Secretary, with Film Club help if needed. Use club-controlled transcription and check it before archiving. In the minutes step, add permanent HTTPS video, audio and transcript links, and retain the approved minutes in their meeting record. A link can be replaced with a history trail. Preserve the archived recording and transcript without editing or deletion. If minutes and recording differ, refer the evidence to the committee for a correction. Members find Watch, Listen and Transcript under My Membership, Notices & newsletters, Meeting archive. The host must enforce the same audience as the archive index.","captureNotes":"Show the step 3 archive fields, playback through member access and a fictional committee minutes correction. Reference: https://github.com/auraofintelligence/Sandy-Sports-Club/blob/1c4983243c8fad3779ca1b2a96c8f59271452177/club-meetings.js","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A generated minute says the club approved a spend when it only discussed an estimate. What do you record?","choices":[{"id":"a","text":"Accept the draft because the figure and item are otherwise correct."},{"id":"b","text":"Correct the minutes against what happened and retain the decision or proposal status and reviewer."}],"correct_choice_id":"b","explanation":"The operating record needs the corrected draft, actual decision, approval version and resulting actions. This lets the next person verify the work and any remaining decision.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]},{"id":"practice-2","type":"single_choice","mode":"practice","prompt":"A member shows a timestamp where the recorded motion differs from approved minutes. What does the Secretary do?","choices":[{"id":"a","text":"Keep the original recording and transcript, then put a supported minutes correction to the committee."},{"id":"b","text":"Trim that portion from the archived recording."},{"id":"c","text":"Replace the official minutes with the transcript without a decision."}],"correct_choice_id":"a","explanation":"The completed recording is evidence and the committee corrects the formal minutes.","source_refs":["https://github.com/auraofintelligence/Sandy-Sports-Club/blob/1c4983243c8fad3779ca1b2a96c8f59271452177/club-meetings.js"]}]}'),
    '$[3]', json('{"title":"Prepare nominations, AGM and future filings","body":"Build a checklist for nominations, record status, papers, notices, meeting basis, voting, reports and office transition. Use current guidance and the actual rules when statutory steps apply. Track evidence, responsible officers and dates for each item. Keep a future AGM rehearsal distinct from a formation meeting and flag any steps waiting on establishment. Check who would record a later appointment or filing and where the receipt belongs.\n\nKeep the status of each AGM or formation step, responsible officer and source to check in the authorised record.\n\nCheck that the nomination contains the Rule 4B consent to recording, archiving and member access before it is processed. Keep the agreed record with the nomination and brief incoming officers on the member archive and public stream rules. The AGM is covered by opening-to-close video and audio and the general meeting notice requirement.","captureNotes":"Show a fictional nomination and the recording agreement as part of the AGM checklist. Reference: https://github.com/auraofintelligence/Sandy-Sports-Club/blob/1c4983243c8fad3779ca1b2a96c8f59271452177/constitution.js","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"The AGM desk shows a rehearsal date and a prospective Treasurer. What does it establish?","choices":[{"id":"a","text":"A plan requiring verification of its governing process, people and notices before any formal step."},{"id":"b","text":"An AGM notice and election record once both fields are filled in."}],"correct_choice_id":"a","explanation":"The operating record needs the status of each AGM or formation step, responsible officer and source to check. This lets the next person verify the work and any remaining decision.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]},{"id":"practice-2","type":"single_choice","mode":"practice","prompt":"The AGM nomination checklist already shows eligibility. Which further declaration does draft Rule 4B call for?","choices":[{"id":"a","text":"The candidate allows the Film Club to publish all footage to anyone."},{"id":"b","text":"The candidate takes ownership of the entire meeting archive when elected."},{"id":"c","text":"The candidate agrees to recording, archiving and access by members for meetings they attend under the rule."}],"correct_choice_id":"c","explanation":"Nomination consent covers the recording and member access described by Rule 4B.","source_refs":["https://github.com/auraofintelligence/Sandy-Sports-Club/blob/1c4983243c8fad3779ca1b2a96c8f59271452177/constitution.js"]}]}')
  ),
  practical='Using fictional records, produce a Secretary’s file with a versioned rules proposal, notice and recipient log, agenda and reviewed minutes, nomination and follow-up checklist, and one member or volunteer case with privacy and approval boundaries. Include a newsletter release plan and an indexed handover. Mark which work is formation preparation and which needs future authority. Pass when the next Secretary can verify each action and no proposed decision, message or applicant is recorded as formally approved. Add a Rule 4B notice and nomination check, a continuous video and audio plan with named operators, a club-controlled transcript, permanent member archive links and an evidenced minutes correction.',
  edit_version=edit_version+1
WHERE course_id='sandy-secretary' AND revision=1 AND state='draft' AND edit_version=3 AND edited_by IS NULL;

UPDATE learning_course_versions SET
  lessons_json=json_set(lessons_json,
    '$[5]', json('{"title":"Confirm integrations, backups and recovery","body":"Verify actual decisions for hosted email, identity, pay services, media links or other processors before enabling them. Agree scope, service owner, deployment and runtime credential custody, costs and records. Back up agreed data and rehearse restoration with authorised test data. Check access and recent write history after recovery. Track outages, restore limits and how changes will be reviewed with the operator.\n\nKeep the approved provider or backup scope, recovery owner and test results in the authorised record.\n\nFor the Rule 4B meeting archive, support the Secretary with durable club-controlled hosting, independent backups and access checks at the actual media host. The archive stores stable HTTPS references to video, audio and transcripts. Verify a signed-out visitor cannot open a copied member-only media URL. A public meeting replay uses the public hosting route. If hosting moves, preserve the original media and relevant access, then have the Secretary replace the archive link with its history intact.","captureNotes":"Demonstrate a fictional archive backup restore and test the old and new access with a real role test fixture. Reference: https://github.com/auraofintelligence/Sandy-Sports-Club/blob/1c4983243c8fad3779ca1b2a96c8f59271452177/club-meetings.js","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A backup exists but has never been restored. What evidence is missing?","choices":[{"id":"a","text":"Proof that the backup file has the latest timestamp."},{"id":"b","text":"A recovery rehearsal with the expected records, permissions, steps and outcomes checked."}],"correct_choice_id":"b","explanation":"The operating record needs the approved provider or backup scope, recovery owner and test results. This lets the next person verify the work and any remaining decision.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]},{"id":"practice-2","type":"single_choice","mode":"practice","prompt":"The member archive index denies signed-out users, but a copied video URL plays. What must the Webmaster verify?","choices":[{"id":"a","text":"Access is enforced at the media host, then the copied link is denied signed out and works for the intended member."},{"id":"b","text":"The index alone will revoke access to the copied URL."},{"id":"c","text":"The public player includes a warning saying the video is for members."}],"correct_choice_id":"a","explanation":"The website can protect its own index. The media host protects its own files.","source_refs":["https://github.com/auraofintelligence/Sandy-Sports-Club/blob/1c4983243c8fad3779ca1b2a96c8f59271452177/club-meetings.js"]}]}')
  ),
  practical='Prepare a fictional controlled change and handover. Show an authorised reserved-seat invitation and expiry or revocation, separate real-role access tests with private paths denied where appropriate, a safe public release and rollback, one privacy or support escalation, and a restore rehearsal. Record provider and backup owners and pending integration decisions. Pass when the evidence distinguishes previews from actual access and the successor can verify, restore and hand over the service. Include a Rule 4B restore and access test. Show that a copied member-only URL is denied signed out, that the media has durable backups and that a changed link preserves its history.',
  edit_version=edit_version+1
WHERE course_id='sandy-webmaster' AND revision=1 AND state='draft' AND edit_version=2 AND edited_by IS NULL;

UPDATE learning_course_versions SET
  lessons_json=json_set(lessons_json,
    '$[7]', json('{"title":"Connect production to Island News and live coverage","body":"Send Island News stories through the Film Club member form with their approved scope, credit and sources. An authorised editor reviews the story and hands a permitted copy to the network steward. For an approved Sandy public meeting, assign a crew to run the external encoder, audio, continuous local recording and viewer check. The Secretary is responsible, the Secretary or Assistant Secretary makes the recording, and the officers with Members and publishing access under Schedule 1 approve public streams. Film Club crew may operate the equipment. Plan for full video and audio from opening to close and the complete public replay on Island News and Live. Give the Secretary the original files and verified links for archive and transcription. Follow separate event permissions and the network steward’s review when sharing externally.","captureNotes":"Show a fictional crew sheet, the Schedule 1 approval handoff and the complete recording handoff to the Secretary. Reference: https://sandy-sports-club.auraofintelligence.workers.dev/how-it-works.html#flow-recording","questions":[{"id":"practice-1","type":"single_choice","mode":"practice","prompt":"The Film Club producer and camera operator are ready, but there is no signed-in editor authorised to manage the news listing. What next?","choices":[{"id":"a","text":"Arrange an authorised publisher and agree the release plan before going publicly live."},{"id":"b","text":"Ask the camera operator to use the editor’s account."},{"id":"c","text":"Publish it on an unrelated personal channel and notify the club later."}],"correct_choice_id":"a","explanation":"The producer runs capture and makes sure the editor is available for the distinct publishing decision.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/how-it-works.html#flow-broadcast"]},{"id":"practice-2","type":"single_choice","mode":"practice","prompt":"You have a highlight reel and a complete Sandy public forum recording. Which goes to the official replay and archive?","choices":[{"id":"a","text":"Publish the highlights as the official replay and discard the full recording."},{"id":"b","text":"Use the complete recording for the public replay and give the unedited original video and audio to the Secretary for the archive."},{"id":"c","text":"Send only the transcript and ask the steward to create a new master."}],"correct_choice_id":"b","explanation":"Rule 4B keeps the full recording and its public replay. A highlight is a separate production.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/how-it-works.html#flow-recording"]}]}')
  ),
  practical='Build a fictional screening or film workshop pack. Include format and scope, venue and screening or participant permissions, a cue sheet and roster, sound and caption checks, approvals for one paid or hired item, a plan for a failure or weather change, and release and gear handover. Pass when the duty owners can set up and pause the event, all intended uses have reviewed authority, and any open permission or equipment issue is easy to find. Include a lane and kit-loan plan and show who is authorised to release a story or list, stop and review a live broadcast. The assessor should check the Screen Media Network handoff and the replay permission boundary. For an example Rule 4B meeting, hand a full unedited recording to the Secretary and show the Schedule 1 approval and complete public replay route.',
  edit_version=edit_version+1
WHERE course_id='sandy-film-lead' AND revision=1 AND state='draft' AND edit_version=3 AND edited_by IS NULL;

UPDATE learning_course_versions SET
  lessons_json=json_set(lessons_json,
    '$[4]', json('{"title":"Prepare a broadcast listing and approve its replay","body":"Confirm date and Brisbane time, place, audience, public viewer URL and private crew notes. For a Sandy public meeting under draft Rule 4B, officers with Members and publishing access under Schedule 1 approve the stream and the notice includes public streaming. Coordinate with the Secretary and Film Club crew on the opening and closing cues and full local capture. Use the Island News desk to reflect the actual external host state. The full public meeting recording stays as a replay on Island News. Verify the replay opens publicly and give the Secretary its reference. Use the Noticeboard export for an agreed broadcast handoff to the receiving steward. A general meeting streamed to members uses a member-authorised channel.","captureNotes":"Show verified public status and a full meeting replay in a fictional source, then contrast it with the member-authorised host setting. Reference: https://sandy-sports-club.auraofintelligence.workers.dev/how-it-works.html#flow-recording","questions":[{"id":"practice-1","type":"single_choice","mode":"practice","prompt":"What should go in the public scheduled stream field?","choices":[{"id":"a","text":"The public viewing URL verified from a separate device."},{"id":"b","text":"The encoder stream key so the partner can publish too."},{"id":"c","text":"A private organiser edit link."}],"correct_choice_id":"a","explanation":"The viewer URL is designed to be public. Stream keys and admin links remain private.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/how-it-works.html#flow-broadcast"]},{"id":"practice-2","type":"single_choice","mode":"practice","prompt":"The crew sends a four-minute cut from a public forum. What should stay on Island News as the Rule 4B replay?","choices":[{"id":"a","text":"The cut that is easiest to share."},{"id":"b","text":"The complete public meeting recording, linked and checked with the Secretary and crew."},{"id":"c","text":"Any short clip that contains the final motion."}],"correct_choice_id":"b","explanation":"A public meeting replay preserves the whole meeting. A highlight can have its own editorial review.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/how-it-works.html#flow-recording"]}]}')
  ),
  practical='In a simulated news desk, triage two stories, review their rights and source evidence, publish one mock release and return the other with reasons. Hand off a reviewed export and demonstrate a correction or withdrawal across a second fictional channel. For the meeting example, show the Schedule 1 public approval, verified outside viewing and the complete Rule 4B public replay link.',
  edit_version=edit_version+1
WHERE course_id='sandy-island-news-editor' AND revision=1 AND state='draft' AND edit_version=1 AND edited_by IS NULL;

UPDATE learning_course_versions SET
  lessons_json=json_set(lessons_json,
    '$[4]', json('{"title":"From committee decisions to ongoing work","body":"Open the meeting and AGM flow. Find who prepares the agenda, how the meeting becomes an approved record, and how follow-up tasks reach officers. Then check the officer access flow for a resolution, invitation and handover. Browse the newsletter, sponsorship and store examples to identify the human decision and the record it leaves. If a handoff stalls, follow the flow to the next actor and share the task reference through the appropriate channel.\n\nFollow Recording and archiving meetings (rule 4B) as a worked example. Find who makes the recording, who signs off a public stream and where a member goes to Watch, Listen or read a Transcript. Committee and general meetings, including the AGM, are recorded in full under the draft rule. Find the complete public meeting replay on Island News and Live and compare that path with the permanent member archive.","captureNotes":"Show the live Rule 4B process flow and a synthetic member archive next to the public replay link. Reference: https://sandy-sports-club.auraofintelligence.workers.dev/how-it-works.html#flow-recording"}')
  ),
  edit_version=edit_version+1
WHERE course_id='sandy-how-it-works' AND revision=1 AND state='draft' AND edit_version=1 AND edited_by IS NULL;

UPDATE learning_course_versions SET
  lessons_json=json_set(lessons_json,
    '$[2]', json('{"title":"Explore the useful pages by goal","body":"Use Sport and programme pages for activities, Film Club for screenings and workshops, Places and Facilities for options, and Join to offer interest or skills. Check the stage and contact rather than treating a visual concept or budget example as an operating facility.\n\nUse How it works to follow the Rule 4B recording and archive flow. Public meetings are streamed and kept as replays on Island News and Live under the draft rule. Signed-in members find the Meeting archive under Notices & newsletters.","captureNotes":"Show the public process map and where a participant can find a public replay. Use a demo for the signed-in archive. Reference: https://sandy-sports-club.auraofintelligence.workers.dev/how-it-works.html#flow-recording"}')
  ),
  edit_version=edit_version+1
WHERE course_id='sandy-site-tour' AND revision=1 AND state='draft' AND edit_version=2 AND edited_by IS NULL;

UPDATE learning_course_versions SET
  lessons_json=json_set(lessons_json,
    '$[4]', json('{"title":"Have a say and manage your details","body":"Offer specific ideas based on local needs, attend agreed discussions and ask how proposals are recorded and decided. Use the approved way to check or correct your contact choices. Ask before sharing other people’s images, messages or membership details.\n\nTo check meeting information, start with the notice. Under Sandy’s draft Rule 4B, committee and general meetings have a permanent member recording archive. Open My Membership, Notices & newsletters, then Meeting archive. Public meeting replays also have a public route through Island News and Live.","captureNotes":"Show the two replay routes with fictional meeting titles and links. Reference: https://sandy-sports-club.auraofintelligence.workers.dev/how-it-works.html#flow-recording"}')
  ),
  edit_version=edit_version+1
WHERE course_id='sandy-resident-member' AND revision=1 AND state='draft' AND edit_version=2 AND edited_by IS NULL;

UPDATE learning_course_versions SET
  lessons_json=json_set(lessons_json,
    '$[0]', json('{"title":"Build the run sheet and crew roster","body":"Confirm whether this is a Sandy Rule 4B meeting or a separately authorised event. For a meeting, the Secretary coordinates capture or delegates to the Assistant Secretary, and the Film Club crew may operate. The Schedule 1 Members and publishing group approves a public stream. Name the producer, camera and audio operators, authorised publishing officer and outside-feed checker. Write the opening and closing cues and the continuous local video-and-audio backup plan. Confirm the notice discloses the recording and public stream. Plan for loss of the uplink and any audience or safety issues before opening. For a general meeting streamed to members, check the member-only host access.","captureNotes":"Show a fake run sheet with one public meeting and one members-only general meeting. Reference: https://github.com/auraofintelligence/Sandy-Sports-Club/blob/1c4983243c8fad3779ca1b2a96c8f59271452177/constitution.js","questions":[{"id":"practice-1","type":"single_choice","mode":"practice","prompt":"Which role checks that the outgoing sound is actually reaching a viewer?","choices":[{"id":"a","text":"The room announcer listening to the PA."},{"id":"b","text":"The assigned outside-feed checker using the actual viewing URL."},{"id":"c","text":"The camera operator looking only at their viewfinder."}],"correct_choice_id":"b","explanation":"A check at the viewer end catches sound problems that occur after room and encoder mixing.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/how-it-works.html#flow-broadcast"]},{"id":"practice-2","type":"single_choice","mode":"practice","prompt":"A Rule 4B public meeting run sheet proposes pausing the master recording for one agenda item. What should the crew do?","choices":[{"id":"a","text":"Build that pause into the scheduled meeting record."},{"id":"b","text":"Use camera only for the difficult item."},{"id":"c","text":"Ask the Secretary and Chair to resolve the agenda before opening and plan continuous video and audio through the formal meeting."}],"correct_choice_id":"c","explanation":"Rule 4B calls for opening-to-close recording. Resolve the problem with the meeting officers before it opens.","source_refs":["https://github.com/auraofintelligence/Sandy-Sports-Club/blob/1c4983243c8fad3779ca1b2a96c8f59271452177/constitution.js"]}]}'),
    '$[1]', json('{"title":"Wire picture and sound and rehearse privately","body":"Connect a camera or approved capture feed and the designated microphone input. Listen on headphones and test for clipping, echo, lag, feedback and accidental duplicate audio. Use a neutral holding scene with audio muted or intentionally routed. Set the approved hosting account in OBS or another encoder. Protect stream keys. Test the network and local recording at the venue using a private test stream, then check video, sound and captions from a separate viewer device.\n\nFor a Rule 4B meeting, confirm the local master records independent of the uplink and carries both picture and sound. Test power, file space and the backup before opening.","captureNotes":"Disconnect the practice uplink and confirm uninterrupted local recording. Reference: https://sandy-sports-club.auraofintelligence.workers.dev/how-it-works.html#flow-recording","questions":[{"id":"practice-1","type":"single_choice","mode":"practice","prompt":"A muted microphone is still audible in the stream preview. What should you check?","choices":[{"id":"a","text":"Check all input and desktop or monitoring routes, then confirm silence at the external player."},{"id":"b","text":"Turn off only the camera and resume practice."},{"id":"c","text":"Trust the mute icon without repeating the check."}],"correct_choice_id":"a","explanation":"Room sound can travel through other sources. Check every source the viewer can hear.","source_refs":["https://obsproject.com/kb/quick-start-guide"]},{"id":"practice-2","type":"single_choice","mode":"practice","prompt":"Where does an encoder stream key go?","choices":[{"id":"a","text":"On a laminated sign next to the screen operated by volunteers."},{"id":"b","text":"In authorised encoder or protected credential storage."},{"id":"c","text":"In the public Sandy link field."}],"correct_choice_id":"b","explanation":"The stream key grants authority over the external channel.","source_refs":["https://obsproject.com/kb/quick-start-guide"]}]}'),
    '$[2]', json('{"title":"Go live in the host and link the public feed","body":"Bring the encoder up to the agreed service, check preview and start at the producer’s cue. Have the outside viewer confirm the correct picture and sound. Ask the Sandy editor to set the matching listing to Live and check the site takes viewers to the correct link. If a steward received a Noticeboard handoff, confirm the current schedule and the channel it will use. Keep a short live log of start, audio checks and change decisions.\n\nUse the public listing for a public meeting. Keep a member-only general meeting stream on the member-authorised platform and verify it from inside and outside that audience.","captureNotes":"Show simulated member access and signed-out denial before the test playback. Reference: https://sandy-sports-club.auraofintelligence.workers.dev/how-it-works.html#flow-recording","questions":[{"id":"practice-1","type":"single_choice","mode":"practice","prompt":"Which step makes the footage travel to viewers?","choices":[{"id":"a","text":"Saving a Sandy calendar entry."},{"id":"b","text":"Exporting the Noticeboard scheduling record."},{"id":"c","text":"The properly configured encoder and hosting service send it."}],"correct_choice_id":"c","explanation":"Sandy publicises the external broadcast link. The host and encoder carry the media.","source_refs":["https://support.google.com/youtube/answer/2907883"]},{"id":"practice-2","type":"single_choice","mode":"practice","prompt":"The outside viewer hears unsynchronised audio while the room sounds fine. What should the crew do?","choices":[{"id":"a","text":"Use the fallback or hold scene while diagnosing the outgoing mix and retest externally."},{"id":"b","text":"Leave it because people in the room can hear."},{"id":"c","text":"Increase room PA level so the external timing catches up."}],"correct_choice_id":"a","explanation":"Broadcast input and network paths need a separate check.","source_refs":["https://support.google.com/youtube/answer/2907883"]}]}'),
    '$[3]', json('{"title":"Keep recording through a technical outage","body":"For a Sandy Rule 4B public meeting, keep the local video and audio running continuously when the internet or encoder output fails. Use the independent backup and tell the Secretary and publishing officer, log the outage and its timestamps, restore and verify the public feed where possible, and keep the listing accurate. If an unexpected safety or privacy incident affects public output, follow the agreed incident procedure, notify the responsible officers and preserve authorised source material. The meeting plan calls for full capture through opening and close. A separately authorised event follows its own capture scope and stop signals.","captureNotes":"Rehearse lost internet and external status updates while recorded local time keeps advancing. Reference: https://sandy-sports-club.auraofintelligence.workers.dev/how-it-works.html#flow-recording","questions":[{"id":"practice-1","type":"single_choice","mode":"practice","prompt":"The public viewer loses the stream but the local backup still records the meeting. What should the crew do first?","choices":[{"id":"a","text":"Pause the backup to match the public transmission gap."},{"id":"b","text":"Keep recording the meeting locally, alert the producer and Secretary and check the external problem."},{"id":"c","text":"Erase the first section and start a new single file later."}],"correct_choice_id":"b","explanation":"The permanent source should capture the meeting independently of live delivery.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/how-it-works.html#flow-recording"]},{"id":"practice-2","type":"single_choice","mode":"practice","prompt":"What belongs in the broadcast incident handoff?","choices":[{"id":"a","text":"An assertion that the stream stayed live because the Sandy bar stayed red."},{"id":"b","text":"Only the new public URL and the crew account password."},{"id":"c","text":"Actual times, the effect on the public feed and the status of the local source and backup."}],"correct_choice_id":"c","explanation":"An incident log tells the officers exactly what was recorded and what the audience could reach.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/how-it-works.html#flow-recording"]}]}'),
    '$[4]', json('{"title":"Close the public stream and verify the full replay","body":"Confirm the Chair has closed the Rule 4B meeting and finish the local recording. End the external feed, verify from an outside viewer and have the authorised officer end the Sandy listing. Check local video and audio for continuity and confirm the complete public meeting replay plays from its Island News link. Add captions alongside the replay where possible without altering archived masters. Log any issue with the replay or capture and refer it to the Secretary. For a separately authorised event, the host and editor apply that event’s playback permissions.","captureNotes":"Verify the provider has ended, show the complete public replay and preserve the full source in a fictional archive handoff. Reference: https://sandy-sports-club.auraofintelligence.workers.dev/how-it-works.html#flow-recording","questions":[{"id":"practice-1","type":"single_choice","mode":"practice","prompt":"A public forum finished and the host has a short automatic highlight. What replay goes on Island News under Rule 4B?","choices":[{"id":"a","text":"The complete recording of the public meeting, with its public replay link checked."},{"id":"b","text":"The highlight because it is already ready."},{"id":"c","text":"A minutes PDF linked as if it were the replay."}],"correct_choice_id":"a","explanation":"The draft rule keeps the entire public meeting recording as replay.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/how-it-works.html#flow-recording"]},{"id":"practice-2","type":"single_choice","mode":"practice","prompt":"How do you check the actual broadcast is over?","choices":[{"id":"a","text":"Check only for the missing Sandy live bar."},{"id":"b","text":"Verify the host state and outside viewer, then check the Sandy listing."},{"id":"c","text":"Close the laptop before the host confirms the end."}],"correct_choice_id":"b","explanation":"The encoder, host and Sandy listing are separate places to check.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/how-it-works.html#flow-recording"]}]}'),
    '$[5]', json('{"title":"Return gear and transfer records","body":"Return gear with accessories and fault notes. Hand the Secretary the complete video and audio, backup file check, timing or incident log and the agreed archive and replay references. Send the whole recording through club-controlled transfer. Keep approved original recordings and transcripts intact for the permanent archive, and arrange club-controlled transcription and caption work with the Secretary. If the upload or public replay has gaps, identify them explicitly and hand over the independent source. Escalate any lost recording, unintended exposure or broken member-only access. Assign every unresolved item to a named role with a follow-up date.","captureNotes":"Show a fictional kit return and the full file manifest to the Secretary, including the condition of the original and backup. Reference: https://sandy-sports-club.auraofintelligence.workers.dev/how-it-works.html#flow-recording","questions":[{"id":"practice-1","type":"single_choice","mode":"practice","prompt":"A network outage is visible on the public player but the complete local recording survived. What should you hand over?","choices":[{"id":"a","text":"Give the Secretary only the host’s incomplete copy."},{"id":"b","text":"Hide the outage by replacing the archive with highlights."},{"id":"c","text":"Give the Secretary the complete local master and outage note and use the complete file for the verified public replay."}],"correct_choice_id":"c","explanation":"The independent local master can supply the full record and replay. The record of the outage explains what viewers saw live.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/how-it-works.html#flow-recording"]},{"id":"practice-2","type":"single_choice","mode":"practice","prompt":"You discover that a member-only archive link works when copied into a signed-out browser. What should you do?","choices":[{"id":"a","text":"Report it to the Secretary and media host operator, correct hosting access and retest."},{"id":"b","text":"Leave it because the original index is protected."},{"id":"c","text":"Put the same link on Island News to make it easier to find."}],"correct_choice_id":"a","explanation":"The underlying host must enforce member access independently of the archive index.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/how-it-works.html#flow-recording"]}]}')
  ),
  practical='Use synthetic material for a Rule 4B public meeting. Prepare the notice and Schedule 1 publishing approval with the Secretary, run a private encoder rehearsal, capture uninterrupted local video and audio through opening and close, and verify the viewer on a separate device. Simulate an uplink failure while the capture continues. Close the host and listing, check the complete public replay and captions, and hand the unedited master and link references to the Secretary for the permanent archive. The assessor checks continuity, audience and handoff.',
  edit_version=edit_version+1
WHERE course_id='sandy-live-broadcast-crew' AND revision=1 AND state='draft' AND edit_version=1 AND edited_by IS NULL;

UPDATE learning_course_versions SET
  lessons_json=json_set(lessons_json,
    '$[1]', json('{"title":"Prepare and participate in decisions responsibly","body":"Read the notice, agenda, decision evidence and relevant rules. Declare a relevant interest before discussion or voting and follow the agreed handling. Ask about cost, intended people, actual approvals and who can carry the work. Confirm an accurate decision or note that it remains a proposal. Keep sensitive information inside the authorised audience. Record follow-up in the appropriate desk.\n\nKeep the decision wording, interest handling, limitations and responsible people in the authorised record.\n\nPrepare for draft Rule 4B by checking the agenda, the intended audience and the full video and audio capture with the Secretary before opening. Under the draft rule, nominees agree to recording and member archive access, and general and public notices disclose recording. Refer confidential concerns to the Secretary before the meeting. The recording is continuous, including the AGM. If the archive and minutes disagree, raise the timestamp and correction through the committee.","captureNotes":"Use a fictional nomination, agenda and timestamped minutes correction. Reference: https://github.com/auraofintelligence/Sandy-Sports-Club/blob/1c4983243c8fad3779ca1b2a96c8f59271452177/constitution.js","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"You are connected to a proposed supplier and the committee asks you to contribute to the choice. What first?","choices":[{"id":"a","text":"Say nothing until someone asks specifically about the supplier relationship."},{"id":"b","text":"Raise the interest using the applicable process before the matter is handled."}],"correct_choice_id":"b","explanation":"The operating record needs the decision wording, interest handling, limitations and responsible people. This lets the next person verify the work and any remaining decision.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]},{"id":"practice-2","type":"single_choice","mode":"practice","prompt":"You identify sensitive material on a covered agenda before the meeting. What do you do?","choices":[{"id":"a","text":"Plan a regular off-camera interval in the formal meeting."},{"id":"b","text":"Raise it with the Secretary and Chair before opening so the agenda and recording responsibilities can be resolved."},{"id":"c","text":"Assume that a non-public meeting recording will never be available to members."}],"correct_choice_id":"b","explanation":"The draft rule records the full formal meeting and gives members archive access. Resolve the concern before opening.","source_refs":["https://github.com/auraofintelligence/Sandy-Sports-Club/blob/1c4983243c8fad3779ca1b2a96c8f59271452177/constitution.js"]}]}')
  ),
  edit_version=edit_version+1
WHERE course_id='sandy-committee-member' AND revision=1 AND state='draft' AND edit_version=2 AND edited_by IS NULL;

UPDATE learning_course_versions SET
  lessons_json=json_set(lessons_json,
    '$[5]', json('{"title":"Report, review and prepare records for the AGM","body":"Reconcile actual figures to custody and statements where relevant. Provide budget versus actuals, funding restrictions, outstanding liabilities, stock and asset status, and unresolved evidence. Check the applicable reporting, year end and audit or review requirements with the operator and current Fair Trading guidance as matters become formal. Prepare the report and evidence list for the Chair and Secretary and record the committee decision, any correction and future dates.\n\nKeep the evidence-backed report, variances, applicable review and filing responsibility in the authorised record.\n\nCheck that AGM papers and the report are suitable for the notified audience. The AGM falls under draft Rule 4B and its complete video and audio go to the permanent member archive. Flag unnecessary personal or account details with the Secretary before the papers are released. Officers with Members and publishing access under Schedule 1 can approve a public stream within their delegated authority. The Secretary owns the archive and the committee corrects minutes against recorded evidence.","captureNotes":"Show a fictional AGM finance report and the draft notice and audience check with no real account details. Reference: https://github.com/auraofintelligence/Sandy-Sports-Club/blob/1c4983243c8fad3779ca1b2a96c8f59271452177/constitution.js","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A draft AGM report includes projected income as received. What should the Treasurer do?","choices":[{"id":"a","text":"Separate the forecast and actual position, verify the source and have the corrected report reviewed."},{"id":"b","text":"Leave the figures if the projected total is described as likely in the notes."}],"correct_choice_id":"a","explanation":"The operating record needs the evidence-backed report, variances, applicable review and filing responsibility. This lets the next person verify the work and any remaining decision.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]},{"id":"practice-2","type":"single_choice","mode":"practice","prompt":"The draft AGM report contains a member’s private account details. What is the correct step before the meeting?","choices":[{"id":"a","text":"Raise it with the Secretary and prepare a report suitable for the notified recorded meeting."},{"id":"b","text":"Wait until the item starts and ask the crew to pause the official capture."},{"id":"c","text":"Read the private details and trim them out of the recorded master later."}],"correct_choice_id":"a","explanation":"Prepare appropriate papers before the meeting so the formal recording can remain continuous.","source_refs":["https://github.com/auraofintelligence/Sandy-Sports-Club/blob/1c4983243c8fad3779ca1b2a96c8f59271452177/constitution.js"]}]}')
  ),
  edit_version=edit_version+1
WHERE course_id='sandy-treasurer' AND revision=1 AND state='draft' AND edit_version=2 AND edited_by IS NULL;

UPDATE learning_course_versions SET
  lessons_json=json_set(lessons_json,
    '$[4]', json('{"title":"Review proposals and communications","body":"Check current rules, proposals, dates and approved statements before forwarding them. Ask where to correct your details or change contact preferences. Keep private names and access links within the agreed workflow and raise unclear decisions with the organiser.\n\nReview the draft constitution’s Rule 4B and ask how it would apply at the founding meeting and later AGM. The draft sets out full committee and general meeting recording, permanent member access, notices about recording and public replays when a meeting is public. People standing for office agree through their nomination. Look for which provisions are still proposed and how members can comment before adoption.","captureNotes":"Show the Rule 4B workflow beside the draft constitution using a fictional founding meeting notice. Reference: https://sandy-sports-club.auraofintelligence.workers.dev/how-it-works.html#flow-recording"}')
  ),
  edit_version=edit_version+1
WHERE course_id='sandy-founding-member' AND revision=1 AND state='draft' AND edit_version=2 AND edited_by IS NULL;
